window.HYDRA_SEARCH = [{"url":"index.html","label":"Hydra reference","kind":"Page","description":"A compact guide to the implemented language and standard library."},{"url":"builtins.html#print","label":"print","kind":"Function","description":"print(value, terminator = \"\\n\") — Write one value as text, followed by terminator. Use \"\" to omit the newline."},{"url":"builtins.html#len","label":"len","kind":"Function","description":"len(value) — Count list elements, dict entries, or Unicode characters in a string."},{"url":"builtins.html#has","label":"has","kind":"Function","description":"has(container, key) — Test for a dict key or list index. Negative indices count from the end."},{"url":"builtins.html#get","label":"get","kind":"Function","description":"get(container, key, fallback) — Read a dict key or list index, returning fallback when absent. Does not insert anything."},{"url":"builtins.html#push","label":"push","kind":"Function","description":"push(&list, value) — Append a copied value to a list; return its new length. The list argument must use &."},{"url":"builtins.html#return","label":"return","kind":"Function","description":"return(values*) — Construct a return request. Unconsumed, return its payload from the current function; an empty request returns :null."},{"url":"builtins.html#break","label":"break","kind":"Function","description":"break() — Construct a loop-stop request. Unconsumed, stop the nearest loop in this function; a parallel loop stops as a whole."},{"url":"builtins.html#continue","label":"continue","kind":"Function","description":"continue() — Construct an iteration-stop request. Unconsumed, skip the rest of this iteration; a parallel iteration ends its trail."},{"url":"builtins.html#reject","label":"reject","kind":"Function","description":"reject(msg = :null) — Construct a rejection. Unconsumed in a function, try its next overload. Unhandled exhaustion reports all refusal messages and fails."},{"url":"builtins.html#exit","label":"exit","kind":"Function","description":"exit(code = 0) — Construct an exit request. Unconsumed, stop the program with an integer status from 0 through 255."},{"url":"builtins.html#panic","label":"panic","kind":"Function","description":"panic(msg) — Construct a panic request. Unconsumed, stop the program with a rendered message, call trace, and status 1."},{"url":"builtins.html#alive","label":"alive","kind":"Function","description":"alive() — Whether the current trail is still live. Returns :true outside a trail."},{"url":"builtins.html#channel","label":"channel","kind":"Function","description":"channel() — The current trail’s zero-based index in its block. Requires a trail."},{"url":"builtins.html#send","label":"send","kind":"Function","description":"send(value, to*, mode = :wait) — Send to sibling trails; omit destinations for any sibling. Default :wait waits for receipt; :detach queues one message; :broadcast queues a copy per eligible sibling. False if none remain. Requires a trail."},{"url":"builtins.html#receive","label":"receive","kind":"Function","description":"receive(from*) — Wait for a sibling’s message and its sender index. Omit sources for any sibling. Returns :null, :null once none can send. Requires a trail."},{"url":"builtins.html","label":"Builtins","kind":"Page","description":"Global functions, available without an import."},{"url":"fs.html#join","label":"fs::join","kind":"Function","description":"join(base, parts*) — Join and normalize path components. join(\"a\", \"/b\") yields \"a/b\". Removes .; preserves ..."},{"url":"fs.html#parent","label":"fs::parent","kind":"Function","description":"parent(path) — Parent directory; \".\" if the path has no directory component."},{"url":"fs.html#name","label":"fs::name","kind":"Function","description":"name(path) — Final path component, including its extension."},{"url":"fs.html#stem","label":"fs::stem","kind":"Function","description":"stem(path) — Final component without its last extension."},{"url":"fs.html#extension","label":"fs::extension","kind":"Function","description":"extension(path) — Last extension without its dot; \"\" if absent."},{"url":"fs.html#absolute","label":"fs::absolute","kind":"Function","description":"absolute(path) — Resolve against the working directory. Does not require existence or resolve symlinks."},{"url":"fs.html#cwd","label":"fs::cwd","kind":"Function","description":"cwd() — Current working directory."},{"url":"fs.html#home","label":"fs::home","kind":"Function","description":"home() — Current user’s home directory. Crashes if unavailable."},{"url":"fs.html#temp","label":"fs::temp","kind":"Function","description":"temp() — System temporary directory. Does not create a file or directory."},{"url":"fs.html#exists","label":"fs::exists","kind":"Function","description":"exists(path) — Whether the path exists and can be inspected. Follows symlinks."},{"url":"fs.html#is_file","label":"fs::is_file","kind":"Function","description":"is_file(path) — Whether the path is a regular file. False if absent or inaccessible."},{"url":"fs.html#is_dir","label":"fs::is_dir","kind":"Function","description":"is_dir(path) — Whether the path is a directory. False if absent or inaccessible."},{"url":"fs.html#size","label":"fs::size","kind":"Function","description":"size(path) — Size from filesystem metadata, in bytes. Without a fallback, errors crash."},{"url":"fs.html#modified","label":"fs::modified","kind":"Function","description":"modified(path) — Modification time as Unix seconds, including fractions. Without a fallback, errors crash."},{"url":"fs.html#read","label":"fs::read","kind":"Function","description":"read(path) — Read the whole file as UTF-8. Without a fallback, read and encoding errors crash."},{"url":"fs.html#lines","label":"fs::lines","kind":"Function","description":"lines(path) — Read UTF-8 lines, without line endings. Without a fallback, errors crash."},{"url":"fs.html#list","label":"fs::list","kind":"Function","description":"list(dir, *, match = \"*\", recursive = :false) — List matching entries as paths joined to dir. Sort within each directory; recurse depth-first when requested. Patterns support * and ?. Without a fallback, errors crash."},{"url":"fs.html#write","label":"fs::write","kind":"Function","description":"write(path, text, *, mode = :replace, parents = :true) — Write text; return the path and UTF-8 byte count. :replace truncates, :append appends, :new requires a new file. Creates parent directories by default."},{"url":"fs.html#copy","label":"fs::copy","kind":"Function","description":"copy(source, target, *, overwrite = :true, parents = :true) — Copy a file or directory tree. Overwrite and create parent directories by default. Other failures crash."},{"url":"fs.html#move","label":"fs::move","kind":"Function","description":"move(source, target, *, overwrite = :false, parents = :true) — Rename a file or directory. Create parents by default; existing targets require overwrite = :true. Cross-filesystem moves may fail."},{"url":"fs.html#remove","label":"fs::remove","kind":"Function","description":"remove(path, *, recursive = :false) — Remove a file or empty directory; recursive = :true removes a directory tree. False if absent; other failures crash."},{"url":"fs.html#make_dir","label":"fs::make_dir","kind":"Function","description":"make_dir(path, *, parents = :true) — Create a directory and, by default, its parents. An existing directory is fine; other failures crash."},{"url":"fs.html","label":"fs","kind":"Page","description":"Filesystem paths, inspection, reading, and writing."},{"url":"env.html#args","label":"env::args","kind":"Function","description":"args() — Arguments after --, excluding the script name. Embedding hosts supply these in VM options."},{"url":"env.html#get","label":"env::get","kind":"Function","description":"get(name) — Read a variable. Missing names return fallback, :not_found; non-Unicode values return fallback, :encoding. Without a fallback, failures crash. Invalid names always crash."},{"url":"env.html#all","label":"env::all","kind":"Function","description":"all() — Snapshot Unicode environment variables, sorted by name. Keys are atoms; variables with non-Unicode names or values are omitted."},{"url":"env.html#platform","label":"env::platform","kind":"Function","description":"platform() — Host OS, such as :macos, :linux, or :windows."},{"url":"env.html","label":"env","kind":"Page","description":"Script arguments, environment variables, and the host platform."},{"url":"text.html#split","label":"text::split","kind":"Function","description":"split(text, separator = :null) — With :null, split on Unicode whitespace and discard empty fields. An explicit separator preserves empty fields; an empty separator splits into characters."},{"url":"text.html#join","label":"text::join","kind":"Function","description":"join(parts, separator = \"\") — Join a list of strings with the separator. An empty list produces an empty string."},{"url":"text.html#trim","label":"text::trim","kind":"Function","description":"trim(text) — Remove leading and trailing Unicode whitespace."},{"url":"text.html#replace","label":"text::replace","kind":"Function","description":"replace(text, from, to) — Replace every non-overlapping literal match. An empty from inserts at character boundaries, including both ends."},{"url":"text.html#find","label":"text::find","kind":"Function","description":"find(text, needle) — Zero-based character position of the first literal match; :null if absent. An empty needle matches at zero."},{"url":"text.html#starts_with","label":"text::starts_with","kind":"Function","description":"starts_with(text, prefix) — Whether text begins with the literal prefix."},{"url":"text.html#ends_with","label":"text::ends_with","kind":"Function","description":"ends_with(text, suffix) — Whether text ends with the literal suffix."},{"url":"text.html#lower","label":"text::lower","kind":"Function","description":"lower(text) — Unicode lowercase conversion, independent of locale."},{"url":"text.html#upper","label":"text::upper","kind":"Function","description":"upper(text) — Unicode uppercase conversion, independent of locale. May change character count."},{"url":"text.html","label":"text","kind":"Page","description":"Unicode string operations. Positions count characters, not bytes."},{"url":"json.html#parse","label":"json::parse","kind":"Function","description":"parse(text) — Objects become dicts with atom keys; arrays become lists; booleans and null become :true, :false, and :null. Invalid input gives fallback, :invalid, or crashes without a fallback."},{"url":"json.html#stringify","label":"json::stringify","kind":"Function","description":"stringify(value, *, pretty = :false) — Encode values, preserving dict order. Other atoms become JSON strings. pretty = :true indents. Functions, non-finite numbers, cycles, and excessive nesting crash."},{"url":"json.html","label":"json","kind":"Page","description":"Convert between JSON text and Hydra values."},{"url":"io.html#read","label":"io::read","kind":"Function","description":"read(*, stream = :stdin) — Read stdin to EOF, preserving line endings. Empty input produces an empty string."},{"url":"io.html#read_line","label":"io::read_line","kind":"Function","description":"read_line(*, stream = :stdin) — Read one line, removing its LF or CRLF ending. EOF produces :null; an empty line produces an empty string."},{"url":"io.html#lines","label":"io::lines","kind":"Function","description":"lines(*, stream = :stdin) — Read stdin to EOF as a list of lines, without line endings. This collects the entire input."},{"url":"io.html#write","label":"io::write","kind":"Function","description":"write(value, *, stream = :stdout) — Render one value without a newline to :stdout or :stderr, flush, and return its UTF-8 byte count. Failures crash."},{"url":"io.html#flush","label":"io::flush","kind":"Function","description":"flush(stream = :stdout) — Flush :stdout or :stderr. Failures crash."},{"url":"io.html#is_terminal","label":"io::is_terminal","kind":"Function","description":"is_terminal(stream = :stdout) — Whether :stdin, :stdout, or :stderr is connected to a terminal."},{"url":"io.html","label":"io","kind":"Page","description":"UTF-8 standard input, output, and error streams."},{"url":"time.html#now","label":"time::now","kind":"Function","description":"now() — Unix timestamp with fractional seconds. The system clock can jump."},{"url":"time.html#monotonic","label":"time::monotonic","kind":"Function","description":"monotonic() — Elapsed seconds from the host process’s first call. Use differences to measure durations; unrelated to calendar time."},{"url":"time.html#sleep","label":"time::sleep","kind":"Function","description":"sleep(seconds) — Wait a finite, nonnegative number of seconds while other trails run. Scheduling can make the actual wait longer."},{"url":"time.html#parse","label":"time::parse","kind":"Function","description":"parse(text) — Parse an RFC 3339 timestamp with an explicit offset or Z. Return Unix seconds; invalid input gives fallback, :invalid, or crashes without a fallback."},{"url":"time.html#format","label":"time::format","kind":"Function","description":"format(timestamp, format = \"%+\") — Format Unix seconds in UTC using strftime directives such as %Y-%m-%d %H:%M:%S. Default %+ produces RFC 3339. Invalid formats or dates crash."},{"url":"time.html","label":"time","kind":"Page","description":"Clocks, sleeping, and timestamp conversion. All durations use seconds."},{"url":"http.html#request","label":"http::request","kind":"Function","description":"request(method, url, *, body = :null, headers = {}, timeout = 30, max_bytes = 16777216) — Send a method string or atom, with an optional UTF-8 body. Response fields are .status, .headers, .body, and final .url. HTTP error statuses remain ordinary responses."},{"url":"http.html#get","label":"http::get","kind":"Function","description":"get(url, *, headers = {}, timeout = 30, max_bytes = 16777216) — GET shorthand for request. Response body must be UTF-8."},{"url":"http.html#post","label":"http::post","kind":"Function","description":"post(url, body, *, headers = {}, timeout = 30, max_bytes = 16777216) — POST a UTF-8 string. Set content-type explicitly; use json::stringify for JSON payloads."},{"url":"http.html#head","label":"http::head","kind":"Function","description":"head(url, *, headers = {}, timeout = 30, max_bytes = 16777216) — HEAD shorthand. Return status and headers with an empty .body, even when content-length describes a nonempty resource."},{"url":"http.html#put","label":"http::put","kind":"Function","description":"put(url, body, *, headers = {}, timeout = 30, max_bytes = 16777216) — PUT a UTF-8 string. Set content-type explicitly; use json::stringify for JSON payloads."},{"url":"http.html#patch","label":"http::patch","kind":"Function","description":"patch(url, body, *, headers = {}, timeout = 30, max_bytes = 16777216) — PATCH with a UTF-8 string. Set the content-type required by the server’s patch format."},{"url":"http.html#delete","label":"http::delete","kind":"Function","description":"delete(url, *, body = :null, headers = {}, timeout = 30, max_bytes = 16777216) — DELETE shorthand, with an optional named body."},{"url":"http.html#options","label":"http::options","kind":"Function","description":"options(url, *, body = :null, headers = {}, timeout = 30, max_bytes = 16777216) — OPTIONS shorthand, with an optional named body. Inspect response headers for supported operations."},{"url":"http.html#connect","label":"http::connect","kind":"Function","description":"connect(url, *, headers = {}, timeout = 30, max_bytes = 16777216) — Send CONNECT using the URL’s authority as the request target. Return the handshake response and close the connection; tunnel streams are not exposed."},{"url":"http.html#trace","label":"http::trace","kind":"Function","description":"trace(url, *, headers = {}, timeout = 30, max_bytes = 16777216) — TRACE shorthand. Return the server’s diagnostic response."},{"url":"http.html#download","label":"http::download","kind":"Function","description":"download(url, path, *, headers = {}, timeout = 30, max_bytes = 16777216) — GET binary data to a file. Require a 2xx status, create parent directories, and replace the target only after the complete bounded download succeeds. Failure leaves an existing target intact."},{"url":"http.html","label":"http","kind":"Page","description":"HTTP and HTTPS requests, text responses, and binary downloads."},{"url":"list.html#range","label":"list::range","kind":"Function","description":"range(start, end = :null, step = 1) — Exclusive integer range. One argument means 0 through start-1; negative steps count down. Step must be nonzero; integers must be exactly representable."},{"url":"list.html#repeat","label":"list::repeat","kind":"Function","description":"repeat(value, count) — Copy value count times."},{"url":"list.html#map","label":"list::map","kind":"Function","description":"map(items, f) — Apply f(item) to each item."},{"url":"list.html#filter","label":"list::filter","kind":"Function","description":"filter(items, f) — Keep items whose f(item) is truthy."},{"url":"list.html#filter_map","label":"list::filter_map","kind":"Function","description":"filter_map(items, f) — Map and omit only :null; retain :false and zero."},{"url":"list.html#flat_map","label":"list::flat_map","kind":"Function","description":"flat_map(items, f) — Map each item to a list, then flatten one level."},{"url":"list.html#flatten","label":"list::flatten","kind":"Function","description":"flatten(items) — Concatenate one level of nested lists."},{"url":"list.html#enumerate","label":"list::enumerate","kind":"Function","description":"enumerate(items) — Produce [index, value] pairs, starting at zero."},{"url":"list.html#rev","label":"list::rev","kind":"Function","description":"rev(items) — Reverse item order."},{"url":"list.html#chain","label":"list::chain","kind":"Function","description":"chain(left, right) — Concatenate two lists."},{"url":"list.html#zip","label":"list::zip","kind":"Function","description":"zip(left, right) — Pair corresponding items; stop at the shorter list."},{"url":"list.html#unzip","label":"list::unzip","kind":"Function","description":"unzip(items) — Split a list of two-element pairs into two returned lists."},{"url":"list.html#interleave","label":"list::interleave","kind":"Function","description":"interleave(left, right) — Alternate left and right items, retaining the longer list’s remainder."},{"url":"list.html#cartesian_product","label":"list::cartesian_product","kind":"Function","description":"cartesian_product(left, right) — Every [left, right] pair, in left-major order."},{"url":"list.html#intersperse","label":"list::intersperse","kind":"Function","description":"intersperse(items, separator) — Insert separator between adjacent items."},{"url":"list.html#take","label":"list::take","kind":"Function","description":"take(items, count) — Keep at most count leading items."},{"url":"list.html#skip","label":"list::skip","kind":"Function","description":"skip(items, count) — Omit at most count leading items."},{"url":"list.html#step_by","label":"list::step_by","kind":"Function","description":"step_by(items, step) — Keep every step-th item, starting with the first. Step must be positive."},{"url":"list.html#take_while","label":"list::take_while","kind":"Function","description":"take_while(items, f) — Keep the leading items satisfying f; stop at the first failure."},{"url":"list.html#skip_while","label":"list::skip_while","kind":"Function","description":"skip_while(items, f) — Skip the leading items satisfying f, then keep everything else."},{"url":"list.html#map_while","label":"list::map_while","kind":"Function","description":"map_while(items, f) — Map until f first returns :null; omit that result."},{"url":"list.html#chunks","label":"list::chunks","kind":"Function","description":"chunks(items, size) — Non-overlapping lists of positive size; include the final partial chunk."},{"url":"list.html#windows","label":"list::windows","kind":"Function","description":"windows(items, size) — Overlapping lists of positive size; include complete windows only."},{"url":"list.html#first","label":"list::first","kind":"Function","description":"first(items) — First item, or :null for an empty list."},{"url":"list.html#last","label":"list::last","kind":"Function","description":"last(items) — Last item, or :null for an empty list."},{"url":"list.html#nth","label":"list::nth","kind":"Function","description":"nth(items, index) — Item at a nonnegative zero-based index, or :null if absent."},{"url":"list.html#find","label":"list::find","kind":"Function","description":"find(items, f) — First item satisfying f, or :null."},{"url":"list.html#find_map","label":"list::find_map","kind":"Function","description":"find_map(items, f) — First non-null f(item), stopping immediately."},{"url":"list.html#position","label":"list::position","kind":"Function","description":"position(items, f) — First zero-based index satisfying f."},{"url":"list.html#rposition","label":"list::rposition","kind":"Function","description":"rposition(items, f) — Last zero-based index satisfying f; search backwards."},{"url":"list.html#any","label":"list::any","kind":"Function","description":"any(items, f) — Whether any item satisfies f; short-circuit. False for an empty list."},{"url":"list.html#all","label":"list::all","kind":"Function","description":"all(items, f) — Whether every item satisfies f; short-circuit. True for an empty list."},{"url":"list.html#count","label":"list::count","kind":"Function","description":"count(items) — Number of items; equivalent to len(items)."},{"url":"list.html#fold","label":"list::fold","kind":"Function","description":"fold(items, initial, f) — Apply f(accumulator, item) from left to right, starting with initial."},{"url":"list.html#reduce","label":"list::reduce","kind":"Function","description":"reduce(items, f) — Fold using the first item as accumulator; :null for an empty list."},{"url":"list.html#sum","label":"list::sum","kind":"Function","description":"sum(items) — Sum numeric items; zero for an empty list."},{"url":"list.html#product","label":"list::product","kind":"Function","description":"product(items) — Multiply numeric items; one for an empty list."},{"url":"list.html#join","label":"list::join","kind":"Function","description":"join(items, separator = \"\") — Render items as text and join with separator."},{"url":"list.html#for_each","label":"list::for_each","kind":"Function","description":"for_each(items, f) — Call f(item) in order, consuming and discarding each result."},{"url":"list.html#inspect","label":"list::inspect","kind":"Function","description":"inspect(items, f) — Call f(item) in order for side effects; return the original list."},{"url":"list.html#partition","label":"list::partition","kind":"Function","description":"partition(items, f) — Return two lists, preserving order, partitioned by f(item)."},{"url":"list.html#unique","label":"list::unique","kind":"Function","description":"unique(items) — Keep the first occurrence of each deeply equal value."},{"url":"list.html#unique_by","label":"list::unique_by","kind":"Function","description":"unique_by(items, f) — Keep the first item for each deeply equal f(item) key."},{"url":"list.html#dedup","label":"list::dedup","kind":"Function","description":"dedup(items) — Remove consecutive duplicate values."},{"url":"list.html#dedup_by","label":"list::dedup_by","kind":"Function","description":"dedup_by(items, f) — Remove an item when f(last_retained, item) is truthy."},{"url":"list.html#dedup_by_key","label":"list::dedup_by_key","kind":"Function","description":"dedup_by_key(items, f) — Remove consecutive items with equal f(item) keys."},{"url":"list.html#counts","label":"list::counts","kind":"Function","description":"counts(items) — Return [value, count] pairs in first-occurrence order."},{"url":"list.html#group_by","label":"list::group_by","kind":"Function","description":"group_by(items, f) — Group all equal f(item) keys as [key, items] pairs, in first-key order."},{"url":"list.html#chunk_by","label":"list::chunk_by","kind":"Function","description":"chunk_by(items, f) — Group consecutive equal f(item) keys as [key, items] pairs."},{"url":"list.html#sorted","label":"list::sorted","kind":"Function","description":"sorted(items) — Stable ascending sort. Supports matching numbers, strings, atoms, or recursively ordered lists."},{"url":"list.html#sorted_by","label":"list::sorted_by","kind":"Function","description":"sorted_by(items, compare) — Stable sort using compare(a, b): negative, zero, or positive for less, equal, or greater."},{"url":"list.html#sorted_by_key","label":"list::sorted_by_key","kind":"Function","description":"sorted_by_key(items, f) — Stable ascending sort by f(item), evaluated once per item."},{"url":"list.html#min","label":"list::min","kind":"Function","description":"min(items) — Smallest ordered item; first wins ties. Empty gives :null."},{"url":"list.html#max","label":"list::max","kind":"Function","description":"max(items) — Largest ordered item; last wins ties. Empty gives :null."},{"url":"list.html#min_by","label":"list::min_by","kind":"Function","description":"min_by(items, compare) — Minimum by numeric comparator; first wins ties. Empty gives :null."},{"url":"list.html#max_by","label":"list::max_by","kind":"Function","description":"max_by(items, compare) — Maximum by numeric comparator; last wins ties. Empty gives :null."},{"url":"list.html#min_by_key","label":"list::min_by_key","kind":"Function","description":"min_by_key(items, f) — Minimum by f(item), evaluated once per item; first wins ties. Empty gives :null."},{"url":"list.html#max_by_key","label":"list::max_by_key","kind":"Function","description":"max_by_key(items, f) — Maximum by f(item), evaluated once per item; last wins ties. Empty gives :null."},{"url":"list.html#combinations","label":"list::combinations","kind":"Function","description":"combinations(items, size) — Size-item selections in input order, without replacement. Equal values at different positions remain distinct."},{"url":"list.html#permutations","label":"list::permutations","kind":"Function","description":"permutations(items, size) — Size-item ordered selections without replacement, in input-index order."},{"url":"list.html","label":"list","kind":"Page","description":"Eager list operations, with Rust-style callbacks and itertools conveniences."},{"url":"cli.html#parser","label":"cli::parser","kind":"Function","description":"parser(*, prog = :null, description = \"\", epilog = \"\", add_help = :true) — Create a copyable parser. prog defaults to the script filename; add_help registers -h and --help."},{"url":"cli.html#add_argument","label":"cli::add_argument","kind":"Function","description":"add_argument(&parser, names*, help = \"\", dest = :null, type = :string, default = :null, required = :false, action = :store, nargs = :null, choices = :null, metavar = :null, const = :null, version = \"\") — Add one positional name or option aliases through &parser. Return fields use atom keys; default dest strips leading dashes and changes hyphens to underscores."},{"url":"cli.html#add_subparser","label":"cli::add_subparser","kind":"Function","description":"add_subparser(&parser, name, child, *, help = \"\", dest = \"command\", required = :true) — Attach a copy of a configured child parser. The chosen command name goes in dest; child fields merge into the result. Commands are required by default."},{"url":"cli.html#parse_args","label":"cli::parse_args","kind":"Function","description":"parse_args(parser, args = :null, *, strict = :true) — Parse explicit string arguments, or script arguments after -- when omitted. With strict = :true, reject unknown arguments and return [] as extras on success; strict = :false returns unknown arguments in extras. Print help/version to stdout and stop with status 0; print input errors to stderr and stop with status 2."},{"url":"cli.html#try_parse_args","label":"cli::try_parse_args","kind":"Function","description":"try_parse_args(parser, args = :null) — Never print or exit. Success gives dict, :null, \"\"; help/version gives :null, :help, text; bad input gives :null, :invalid, diagnostic. Invalid parser definitions still crash."},{"url":"cli.html#format_help","label":"cli::format_help","kind":"Function","description":"format_help(parser) — Render usage, description, arguments, choices, commands, and epilog without printing."},{"url":"cli.html#format_usage","label":"cli::format_usage","kind":"Function","description":"format_usage(parser) — Render the compact usage line without printing."},{"url":"cli.html","label":"cli","kind":"Page","description":"Argument parsers with generated help, typed options, and subcommands."},{"url":"atoms.html#control","label":":break","kind":"Control atom","description":":break — Stop the loop; for a parallel loop, cancel its other iterations."},{"url":"atoms.html#control","label":":continue","kind":"Control atom","description":":continue — End the current iteration."},{"url":"atoms.html#control","label":":return","kind":"Control atom","description":"[:return, …values] — Return the payload; no payload means :null."},{"url":"atoms.html#control","label":":reject","kind":"Control atom","description":"[:reject, msg] — Try the next candidate. Unhandled exhaustion reports every refusal and fails."},{"url":"atoms.html#control","label":":exit","kind":"Control atom","description":"[:exit, code] — Stop with status 0–255."},{"url":"atoms.html#control","label":":panic","kind":"Control atom","description":"[:panic, msg] — Stop with a diagnostic and status 1."},{"url":"atoms.html#true","label":":true","kind":"Atom","description":"Boolean true. Also returned by successful predicates."},{"url":"atoms.html#false","label":":false","kind":"Atom","description":"Boolean false; falsy."},{"url":"atoms.html#null","label":":null","kind":"Atom","description":"Absence or an empty result; falsy. Everything else is truthy, including 0 and empty collections."},{"url":"atoms.html#wait","label":":wait","kind":"Atom","description":"Wait until a sibling receives the message. Default for send."},{"url":"atoms.html#detach","label":":detach","kind":"Atom","description":"Queue for one eligible sibling and continue immediately."},{"url":"atoms.html#broadcast","label":":broadcast","kind":"Atom","description":"Queue one copy for each eligible sibling already spawned."},{"url":"atoms.html#replace","label":":replace","kind":"Atom","description":"Create or truncate a file. Default for fs::write."},{"url":"atoms.html#append","label":":append","kind":"Atom","description":"Append to a file; in cli, collect repeated argument values."},{"url":"atoms.html#new","label":":new","kind":"Atom","description":"Create a new file; fail if it already exists."},{"url":"atoms.html#not_found","label":":not_found","kind":"Atom","description":"Path does not exist."},{"url":"atoms.html#denied","label":":denied","kind":"Atom","description":"Permission denied."},{"url":"atoms.html#exists","label":":exists","kind":"Atom","description":"Path already exists."},{"url":"atoms.html#is_dir","label":":is_dir","kind":"Atom","description":"A file operation encountered a directory."},{"url":"atoms.html#not_dir","label":":not_dir","kind":"Atom","description":"A directory operation encountered a non-directory."},{"url":"atoms.html#encoding","label":":encoding","kind":"Atom","description":"Invalid data, including non-UTF-8 text."},{"url":"atoms.html#io","label":":io","kind":"Atom","description":"Other I/O failure."},{"url":"atoms.html#stdin","label":":stdin","kind":"Atom","description":"Input stream for io readers and is_terminal."},{"url":"atoms.html#stdout","label":":stdout","kind":"Atom","description":"Default stream for io::write, flush, and is_terminal."},{"url":"atoms.html#stderr","label":":stderr","kind":"Atom","description":"Error output stream for io::write, flush, and is_terminal."},{"url":"atoms.html#invalid","label":":invalid","kind":"Atom","description":"Malformed JSON, timestamp, or command-line input."},{"url":"atoms.html#timeout","label":":timeout","kind":"Atom","description":"HTTP operation exceeded its time limit."},{"url":"atoms.html#dns","label":":dns","kind":"Atom","description":"HTTP hostname could not be resolved."},{"url":"atoms.html#tls","label":":tls","kind":"Atom","description":"TLS negotiation or certificate verification failed."},{"url":"atoms.html#network","label":":network","kind":"Atom","description":"Other HTTP connection or protocol failure."},{"url":"atoms.html#redirect","label":":redirect","kind":"Atom","description":"HTTP redirect limit or redirect failure."},{"url":"atoms.html#too_large","label":":too_large","kind":"Atom","description":"HTTP response exceeded max_bytes."},{"url":"atoms.html#http_status","label":":http_status","kind":"Atom","description":"A download received a non-2xx response. Other HTTP functions return the response normally."},{"url":"atoms.html#string","label":":string","kind":"Atom","description":"Parse a command-line value as text; default type."},{"url":"atoms.html#int","label":":int","kind":"Atom","description":"Parse a command-line value as an exactly representable integer."},{"url":"atoms.html#float","label":":float","kind":"Atom","description":"Parse a command-line value as a finite number."},{"url":"atoms.html#store","label":":store","kind":"Atom","description":"Store an argument value; default action."},{"url":"atoms.html#store_true","label":":store_true","kind":"Atom","description":"A present flag stores :true; absent defaults to :false."},{"url":"atoms.html#store_false","label":":store_false","kind":"Atom","description":"A present flag stores :false; absent defaults to :true."},{"url":"atoms.html#store_const","label":":store_const","kind":"Atom","description":"A present flag stores const."},{"url":"atoms.html#append_const","label":":append_const","kind":"Atom","description":"Each occurrence appends const to a list."},{"url":"atoms.html#count","label":":count","kind":"Atom","description":"Count occurrences of an option."},{"url":"atoms.html#help","label":":help","kind":"Atom","description":"Show parser help; also the non-exiting parser’s help/version reason."},{"url":"atoms.html#version","label":":version","kind":"Atom","description":"Show the configured version text."},{"url":"atoms.html","label":"Atoms & handlers","kind":"Page","description":"Atoms are ordinary values. Functions and handlers recognize particular names and list shapes."},{"url":"language.html#bindings","label":"Bindings & values","kind":"Language","description":":= declares; = assigns; _ = expression explicitly discards a result. Lists and dicts copy by value. Use &place to pass a reference; mutations through it reach the caller."},{"url":"language.html#calls","label":"Calls","kind":"Language","description":"Omit parentheses only for an outer statement or assignment RHS. Arguments use commas; nested calls require parentheses. A first argument starts on the callee’s line. Bare function names are values; zero-argument calls use ()."},{"url":"language.html#spacing","label":"Significant spacing","kind":"Language","description":"f -1 calls with a negative argument; f - 1 subtracts. f [1] calls with a list; f[1] indexes. f &x passes a reference; f & x is bitwise AND. The formatter preserves these distinctions."},{"url":"language.html#continuation","label":"Continuation","kind":"Language","description":"A single newline continues an expression whenever syntax permits. A blank or whitespace-only line stops it. Comment-only lines are transparent. Precedence stays unchanged."},{"url":"language.html#functions","label":"Functions & results","kind":"Language","description":"Blocks close with end; indentation is cosmetic. Parameters can have defaults, require a reference (&x), or collect positional arguments (xs*). Parameters after * or xs* are named-only. return is an ordinary builtin; a bare return calls it with no arguments."},{"url":"language.html#handlers","label":"Control values","kind":"Language","description":"A control builtin constructs an atom or tagged list. Binding, passing, or returning that value consumes it. An expression statement leaves it to a handler. Loop and return handlers stay within the current function; forward a request explicitly to let the caller handle it."},{"url":"language.html#overloads","label":"Overloads & rejection","kind":"Language","description":"Calls try candidates by signature; :reject or [:reject, msg] tries the next candidate. A successful fallback is silent. If all reject, an unconsumed rejection reports all messages and fails. Builtins can be shadowed; ::name explicitly selects a global builtin."},{"url":"language.html#modules","label":"Modules","kind":"Language","description":"use fs imports a module; fs::read(...) selects a function. use fs as files renames it; use fs as * imports its names. Standard modules: fs, env, text, json, io, time, http, list, and cli."},{"url":"language.html#loops","label":"Branches & loops","kind":"Language","description":"Use if / else if / else, for item in items, or while condition. break() stops the nearest loop; continue() skips an iteration. Neither crosses a function boundary. There are no labeled breaks."},{"url":"language.html#trails","label":"Parallel trails","kind":"Language","description":"Each || column is an independent trail; rows do not synchronize. parallel waits for all trails; race cancels losers after a winner finishes. send and receive communicate within the block. Parallel loops support the same loop-control atoms."},{"url":"language.html#atoms","label":"Atoms & strings","kind":"Language","description":"Atoms use :name or :\"quoted name\". Bare names consume punctuation until whitespace, a delimiter (()[]{},:\"), or // / ||. A dict keeps the colon between key and value. Strings are double-quoted; \\(expression) interpolates a value."},{"url":"language.html","label":"Language","kind":"Page","description":"The rules you need to read and write Hydra."}];
